import sympy as sp
import math

# Top-level setup for potential witness expressions
I2 = sp.eye(2)
I3 = sp.eye(3)
O2 = sp.zeros(2, 2)
O3 = sp.zeros(3, 3)

CONDITION_LABELS = [
    "H_1: a and b are non-zero elements of R",
    "¬Q: The intersection of the principal ideals (a) and (b) is generated by m iff m is an LCM of a and b FAILS"
]

N_HYP = 1
NEG_Q_INDEX = 1

def conditions(witness) -> list[bool]:
    try:
        # Handle witness as a dictionary specifying the ring
        if isinstance(witness, dict):
            ring_str = witness.get('ring', '')
            if ring_str == '2Z':
                a = witness['a']
                b = witness['b']
                m = witness['m']
                H1 = (a != 0 and b != 0)
                l = abs(a * b) // math.gcd(a, b)
                m_gen = (abs(m) == l)
                m_lcm = False  # In 2Z, no elements have an LCM
                neg_Q = (m_gen != m_lcm)
                return [bool(H1), bool(neg_Q)]
            elif ring_str.startswith('Z') and ring_str[1:].isdigit():
                n = int(ring_str[1:])
                a = witness['a'] % n
                b = witness['b'] % n
                m = witness['m'] % n
                H1 = (a != 0 and b != 0)
                
                ideal_a = set((a * i) % n for i in range(n))
                ideal_b = set((b * i) % n for i in range(n))
                ideal_ab = ideal_a.intersection(ideal_b)
                ideal_m = set((m * i) % n for i in range(n))
                m_gen = (ideal_m == ideal_ab)
                
                common_multiples = ideal_ab
                m_is_cm = (m in common_multiples)
                
                m_is_lcm = False
                if m_is_cm:
                    m_is_lcm = True
                    for c in common_multiples:
                        divides = False
                        for i in range(n):
                            if (m * i) % n == c:
                                divides = True
                                break
                        if not divides:
                            m_is_lcm = False
                            break
                            
                neg_Q = (m_gen != m_is_lcm)
                return [bool(H1), bool(neg_Q)]

        # Handle witness as a tuple
        if isinstance(witness, tuple):
            if len(witness) == 4:
                ring_type, a, b, m = witness
                if ring_type == '2Z':
                    H1 = (a != 0 and b != 0)
                    l = abs(a * b) // math.gcd(a, b)
                    m_gen = (abs(m) == l)
                    m_lcm = False
                    neg_Q = (m_gen != m_lcm)
                    return [bool(H1), bool(neg_Q)]
            
            if len(witness) == 3:
                a, b, m = witness
                
                # Integers (commutative ring with identity)
                if isinstance(a, int) and isinstance(b, int) and isinstance(m, int):
                    H1 = (a != 0 and b != 0)
                    if a == 0 or b == 0:
                        l = 0
                    else:
                        l = abs(a * b) // math.gcd(a, b)
                    m_gen = (abs(m) == l)
                    m_lcm = (abs(m) == l)
                    neg_Q = (m_gen != m_lcm)
                    return [bool(H1), bool(neg_Q)]
                    
                # Matrices (non-commutative ring)
                if hasattr(a, 'is_zero_matrix'):
                    H1 = not a.is_zero_matrix and not b.is_zero_matrix
                    
                    # In M_n(Q), the two-sided ideal generated by any non-zero matrix is the whole ring
                    ideal_ab_is_whole = not (a.is_zero_matrix or b.is_zero_matrix)
                    ideal_m_is_whole = not m.is_zero_matrix
                    m_gen = (ideal_m_is_whole == ideal_ab_is_whole)
                    
                    def intersect_spaces(A, B):
                        M = A.row_join(-B)
                        null_basis = M.nullspace()
                        if not null_basis:
                            return []
                        int_basis = []
                        for v in null_basis:
                            x = v[:A.shape[1], :]
                            vec = A * x
                            if not vec.is_zero_matrix:
                                int_basis.append(vec)
                        if not int_basis:
                            return []
                        return sp.Matrix.hstack(*int_basis).columnspace()
                        
                    def same_space(basis1, basis2):
                        if not basis1 and not basis2:
                            return True
                        if not basis1 or not basis2:
                            return False
                        M1 = sp.Matrix.hstack(*basis1)
                        M2 = sp.Matrix.hstack(*basis2)
                        return M1.rank() == M2.rank() == sp.Matrix.hstack(M1, M2).rank()
                        
                    int_ab = intersect_spaces(a, b)
                    col_m = m.columnspace()
                    m_lcm = same_space(col_m, int_ab)
                    
                    neg_Q = (m_gen != m_lcm)
                    return [bool(H1), bool(neg_Q)]
                    
    except Exception:
        pass
    
    return [False, False]